import re
lines=open('deliverables/plan.md').read().splitlines()
# group contiguous table lines, check column counts
blocks=[]; cur=[]
for i,l in enumerate(lines,1):
    if l.strip().startswith('|'):
        cur.append((i,l))
    else:
        if cur: blocks.append(cur); cur=[]
if cur: blocks.append(cur)
for b in blocks:
    counts={len(l.strip().strip('|').split('|')) for _,l in b}
    if len(counts)>1:
        print('INCONSISTENT block starting line',b[0][0],'counts',counts)
        for i,l in b: print(i,l[:120])
    else:
        print('OK block line',b[0][0],'rows',len(b),'cols',counts.pop())
